    LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);Button prev=controlBtn("Anterior",android.R.drawable.ic_media_previous),next=controlBtn("Siguiente",android.R.drawable.ic_media_next),retry=controlBtn("Reconectar",android.R.drawable.ic_popup_sync),more=controlBtn("Más",android.R.drawable.ic_menu_more);favButton=controlBtn("Favorito",android.R.drawable.btn_star_big_off);
    for(Button b:new Button[]{prev,favButton,next,retry,more}){b.setTextSize(11);b.setGravity(Gravity.CENTER);controls.addView(b,weight());}card.addView(controls,new LinearLayout.LayoutParams(-1,dp(58)));
