  void showCategories(){clearContent();LinearLayout page=pageBase("Categorías","Todo el contenido, organizado para encontrarlo rápido");String[] cats={"Deportes","Películas","Series","Noticias","Religión","Infantil","Música","Documentales"};GridLayout grid=new GridLayout(this);grid.setColumnCount(getResources().getConfiguration().screenWidthDp>=600?4:2);page.addView(grid,new LinearLayout.LayoutParams(-1,-2));for(int i=0;i<cats.length;i++){final String raw=cats[i];final String c=raw.replace("Infantil","Niños");int n=0;for(Channel ch:all)if(categoryMatch(ch,c))n++;Button b=actionBtn(raw+"\n"+n+" canales",CARD);b.setSingleLine(false);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setTextSize(13);GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=0;gp.height=dp(86);gp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);gp.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(b,gp);b.setOnClickListener(v->showCategoryChannels(c));}}
